from pathlib import Path
import re
p=Path(__file__).parent
css='''*{box-sizing:border-box}body{margin:0;color:#24374e;background:radial-gradient(at 10% 10%,#d2e6f5,transparent 50%),linear-gradient(135deg,#edf1f8,#eef8fa);font:16px Fustat,system-ui,sans-serif;min-height:100vh}header,main,footer{max-width:1000px;margin:auto;padding:25px}header{display:flex;align-items:center;justify-content:space-between}h1{font-size:clamp(35px,6vw,60px);letter-spacing:-2px;line-height:1.05;margin:20px 0}h2{font-size:29px;margin:8px 0 22px}p{line-height:1.6}.eyebrow{font-size:12px;letter-spacing:2px;color:#3b678e;font-weight:800}.glass{background:#ffffffb0;border:1px solid white;border-radius:30px;padding:30px;box-shadow:0 22px 65px #29456b12;backdrop-filter:blur(18px)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.field label{font-weight:700;display:block;margin-bottom:8px}.field small{display:block;color:#63758b;margin:7px 0;font-size:12px}input,select,textarea{width:100%;font:inherit;color:inherit;background:#ffffffb8;border:1px solid #c5d3e2;border-radius:13px;padding:14px;min-height:50px}input:focus,select:focus{outline:3px solid #719cc14f;border-color:#447aa7}.invalid{border:2px solid #c03f55}button{font:inherit;border:1px solid #cedce9;border-radius:14px;background:#ffffffcc;padding:13px 19px;cursor:pointer;color:#24476a}.primary{background:#37699c;color:white}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:25px}.steps{display:flex;gap:7px;margin:25px 0}.step{flex:1;height:7px;background:#d5e0eb;border-radius:8px}.step.active{background:#3d719d}.muted{color:#61758a;font-size:14px}.error{background:#fff0f0;color:#9d2944;border-radius:14px;padding:15px;margin:15px 0}.success{background:#e8f5f1;border-radius:14px;padding:20px;color:#215e53}.summary{display:grid;grid-template-columns:1fr 1fr;gap:12px}.summary div{border-bottom:1px solid #dae3ec;padding:10px 0}.summary small{display:block;color:#6b7c8d}.hidden,[hidden]{display:none!important}footer{font-size:13px;color:#61758a}a{color:#356a94} @media(max-width:650px){.grid,.summary{grid-template-columns:1fr}main{padding:14px}.glass{padding:22px}header{padding:20px}header b{font-size:14px}}'''
script=(p/'intake-schema.js').read_text()+'''\nconst $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let step=0;
const titles=['Vy a vaše domácnost','Příjmy, výdaje a závazky','Stávající hypotéka','Váš záměr','Podrobnosti – můžete doplnit později','Kontrola a předání poradci'];
function data(){return Object.fromEntries(INTAKE_FIELDS.map(f=>[f.id,$(f.id).value.trim()]))}function dl(payload,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function save(ready){const d=data(),errors=intakeValidate(d);if(ready&&errors.length){step=INTAKE_FIELDS.find(f=>f.id===errors[0].id).step;render();showErrors(errors);return}dl({type:'filip-mortgage-intake',version:1,status:ready?'ready':'draft',createdAt:new Date().toISOString(),fields:d},intakeFilename(d.qName,ready));$('status').textContent=ready?'Soubor pojmenovaný podle klienta je připravený ke stažení. Předejte ho svému poradci dohodnutou cestou. Nic se automaticky neodesílá.':'Rozpracovaný dotazník je připravený ke stažení. Později ho načtete tlačítkem Načíst rozpracované.'}
function showErrors(errors){$('errors').hidden=!errors.length;$('errors').innerHTML=errors.map(e=>'<div>'+esc(e.message)+'</div>').join('');document.querySelectorAll('.invalid').forEach(x=>x.classList.remove('invalid'));errors.forEach(e=>$(e.id).classList.add('invalid'));if(errors.length)$(errors[0].id).focus()}
function render(){const d=data();$('heading').textContent=titles[step];$('progress').textContent='Krok '+(step+1)+' ze 6';document.querySelectorAll('.step').forEach((x,i)=>x.classList.toggle('active',i<=step));for(const f of INTAKE_FIELDS){$('wrap-'+f.id).hidden=f.step!==step||!intakeActive(f,d);const required=intakeRequired(f,d);$('label-'+f.id).textContent=f.label+(required?' *':'');$(f.id).setAttribute('aria-required',String(required));$('help-'+f.id).textContent=required?'Povinný údaj pro tuto část formuláře.':'Nepovinné. Pokud nevíte, nechte prázdné.';}$('back').hidden=step===0;$('next').hidden=step===5;$('export').hidden=step!==5;$('review').hidden=step!==5;$('errors').hidden=true;if(step===5){const errors=intakeValidate(d);$('review').innerHTML='<div class="'+(errors.length?'error':'success')+'">'+(errors.length?'Ještě je potřeba doplnit '+errors.length+' údajů.':'Základ pro výpočet je připravený. Nevyplněné nepovinné údaje poradce doplní později.')+'</div><div class="summary">'+INTAKE_FIELDS.filter(f=>intakeActive(f,d)).map(f=>'<div><small>'+esc(f.label)+'</small>'+esc(d[f.id]?(f.type==='select'?f.min.find(x=>x.split('|')[0]===d[f.id])?.split('|')[1]||d[f.id]:d[f.id]):'Nedoplněno')+'</div>').join('')+'</div>'}}
$('fields').innerHTML=INTAKE_FIELDS.map(f=>'<div class="field" id="wrap-'+f.id+'"><label id="label-'+f.id+'" for="'+f.id+'">'+esc(f.label)+(f.required?' *':'')+'</label>'+(f.type==='select'?'<select id="'+f.id+'"><option value="">Vyberte…</option>'+f.min.map(x=>{const [v,l]=x.split('|');return '<option value="'+v+'">'+esc(l)+'</option>'}).join('')+'</select>':'<input id="'+f.id+'" '+(f.type==='number'?'inputmode="decimal"':'type="'+(f.type==='email'?'email':'text')+'" maxlength="500"')+'>')+'<small id="help-'+f.id+'"></small>'+'</div>').join('');
// Optional cash flows are explicitly visible zero defaults; unknown valuations stay blank.
for(const id of ['qOtherIncome','qSaving','bsCash','oldFee'])$(id).value='0';
$('fields').addEventListener('change',render);$('next').onclick=()=>{const errors=intakeValidate(data(),step);if(errors.length){step=INTAKE_FIELDS.find(f=>f.id===errors[0].id).step;render();showErrors(errors);return}step=Math.min(5,step+1);render();window.scrollTo({top:0,behavior:'smooth'})};$('back').onclick=()=>{step--;render()};$('draft').onclick=()=>save(false);$('export').onclick=()=>save(true);$('load').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>75000)throw Error('Soubor je příliš velký.');const d=parseIntake(JSON.parse(await file.text()));for(const f of INTAKE_FIELDS)$(f.id).value=d[f.id];step=0;render();$('status').textContent='Dotazník načten. Zkontrolujte údaje a pokračujte.'}catch(e){$('status').textContent=e.message}finally{$('file').value=''}};render();
'''
html='<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FILIP · Podklady pro hypotéku</title><style>'+ re.sub(r'</?style[^>]*>','',(p/'font-fragment.txt').read_text())+css+'</style><body><header><b>◈ FILIP / VAŠE BYDLENÍ</b><button id="load">Načíst rozpracované</button><input type="file" id="file" accept=".json" hidden></header><main><div class="eyebrow">PRVNÍ KROK K VAŠEMU FINANCOVÁNÍ</div><h1>Začněme vaším plánem.</h1><p>Vyplňte základní údaje, ze kterých poradce připraví možnosti financování. Neznámé nepovinné údaje můžete doplnit později. Povinné položky označené * potřebujeme pro výpočet. Peníze uvádějte v Kč, příjmy a výdaje za měsíc. Odhad částky je možný – označte ho v poznámce.</p><p class="muted">Formulář funguje offline. Nic sám neodesílá a neukládá na server. Fotografie dokladů ani bankovní výpisy sem nepřikládejte; způsob jejich předání domluvíte s poradcem.</p><div class="steps">'+''.join('<span class="step"></span>' for _ in range(6))+'</div><section class="glass"><div class="eyebrow" id="progress"></div><h2 id="heading"></h2><div id="errors" class="error" role="alert" hidden></div><div class="grid" id="fields"></div><div id="review" hidden></div><div class="actions"><button id="back">← Zpět</button><button class="primary" id="next">Pokračovat →</button><button class="primary" id="export" hidden>Dokončit a stáhnout podklady pro poradce</button><button id="draft">Uložit rozpracované</button></div><p id="status" role="status" class="muted"></p></section></main><footer>FILIP · Klientský dotazník v3.2 · Stažený JSON předáte poradci. Dotazník není žádostí o úvěr ani souhlasem s bankovními registry.</footer><script>'+script+'</script></body></html>'
(p/'Klientsky-dotaznik-v3.0.html').write_text(html)
